export function getProfile(users, id) {
  if (!Object.hasOwn(users, id)) {
    return { status: 404, body: { error: { code: "E_PROFILE_NOT_FOUND" } } };
  }
  return { status: 200, body: users[id] };
}

export const archiveProfile = (db, id, now) => {
  db.prepare("UPDATE profiles SET archived_at = ? WHERE id = ? AND archived_at IS NULL").run(now, id);
  return db.prepare("SELECT id, name, archived_at FROM profiles WHERE id = ?").get(id);
};

export const activeProfiles = db =>
  db.prepare("SELECT id, name, archived_at FROM profiles WHERE archived_at IS NULL ORDER BY id").all();
